import { NextRequest, NextResponse } from "next/server";

interface Post {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
}

interface CreatePostBody {
  title?: string;
  content?: string;
}

const posts: Post[] = [
  { id: 1, title: "First Post", content: "This is the first post" },
  { id: 2, title: "Second Post", content: "This is the second post" },
];

export async function GET(): Promise<NextResponse> {
  return NextResponse.json(posts, { status: 200 });
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const body: CreatePostBody = await request.json();

    const { title, content } = body;

    if (!title || !content) {
      return NextResponse.json(
        { error: "Title and content are required" },
        { status: 400 }
      );
    }

    const newPost: Post & { createdAt: string } = {
      id: Date.now(),
      title,
      content,
      createdAt: new Date().toISOString(),
    };

    return NextResponse.json(newPost, { status: 201 });
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }
}

import { NextRequest, NextResponse } from "next/server";

interface Post {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
}

interface UpdatePostBody {
  title?: string;
  content?: string;
}

interface RouteParams {
  params: Promise<{ id: string }>;
}

export async function GET(
  _request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse> {
  const { id } = await params;

  const post: Post = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse> {
  const { id } = await params;

  try {
    const body: UpdatePostBody = await request.json();
    const { title, content } = body;

    const updatedPost: Post = {
      id: parseInt(id, 10),
      title: title || `Post ${id}`,
      content: content || `Updated content for post ${id}`,
      updatedAt: new Date().toISOString(),
    };

    return NextResponse.json(updatedPost, { status: 200 });
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse> {
  const { id } = await params;

  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  );
}

